package main

import (
	"html/template"
	"net/url"
)

var adminTemplate = template.Must(template.New("admin").Funcs(template.FuncMap{"urlquery": url.QueryEscape}).Parse(`<!doctype html>
<html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ファイル転送 操作画面</title>
<style>
:root{--bg:#f3f4f6;--card:#ffffff;--text:#111827;--sub:#4b5563;--line:#d1d5db;--accent:#1d4ed8;--accent2:#dbeafe;--good:#166534;--danger:#b91c1c;--warnbg:#fffbeb;--warn:#92400e}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:"Segoe UI","Yu Gothic UI",sans-serif}.wrap{max-width:1180px;margin:0 auto;padding:22px 18px 60px}.hero{background:#111827;color:#fff;border-radius:20px;padding:22px 24px;margin-bottom:18px}.hero h1{margin:0;font-size:32px}.hero p{margin:8px 0 0;color:#d1d5db;font-size:16px}.layout{display:grid;grid-template-columns:1fr;gap:18px}.card{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:18px;box-shadow:0 1px 2px rgba(0,0,0,.04)}.stepHead{display:flex;align-items:flex-start;gap:12px;margin-bottom:14px}.stepNo{width:38px;height:38px;border-radius:999px;background:#111827;color:#fff;display:grid;place-items:center;font-weight:800;flex:0 0 38px}.stepTitle{font-size:24px;font-weight:800;line-height:1.2}.lead{color:var(--sub);font-size:14px;margin-top:4px}.sectionGrid{display:grid;grid-template-columns:1fr;gap:18px}.pair{display:flex;gap:18px;align-items:flex-start;flex-wrap:wrap}.qr{background:#fff;border:1px solid var(--line);border-radius:14px;padding:10px;width:220px;height:220px;object-fit:contain}.credBox{background:#f9fafb;border:1px solid var(--line);border-radius:14px;padding:14px;min-width:260px}.credTitle{font-size:13px;color:var(--sub);margin-bottom:4px}.credValue{font-size:20px;font-weight:800;word-break:break-all}.codeLike{display:inline-block;background:#eef2ff;color:#1e3a8a;padding:4px 8px;border-radius:8px;font-family:Consolas,monospace;font-size:16px}.warn{background:var(--warnbg);border:1px solid #fcd34d;color:var(--warn);border-radius:14px;padding:12px 14px;font-size:14px;margin-top:12px}.urlCard{border:1px solid var(--line);border-radius:14px;padding:14px;margin-top:12px;background:#fafafa}.urlTop{display:flex;justify-content:space-between;align-items:center;gap:10px}.tag{display:inline-block;background:#dcfce7;color:#166534;border-radius:999px;padding:4px 10px;font-size:12px;font-weight:800}.muted{color:var(--sub);font-size:13px}.bigUrl{font-size:16px;font-weight:700;overflow-wrap:anywhere;margin-top:6px}.btn,.fileLabel{border:0;border-radius:12px;padding:12px 14px;font-size:15px;font-weight:700;cursor:pointer}.primary{background:var(--accent);color:#fff}.secondary{background:#e5e7eb;color:#111827}.danger{background:#fee2e2;color:var(--danger)}.fileLabel input{display:none}.toolRow{display:flex;flex-wrap:wrap;gap:10px}.subgrid{display:grid;grid-template-columns:1fr;gap:18px;margin-top:16px}.panel{background:#f9fafb;border:1px solid var(--line);border-radius:14px;padding:14px}.panel h3{margin:0 0 10px;font-size:18px}.list{margin-top:10px}.file{display:flex;padding:10px 0;border-bottom:1px solid var(--line);gap:10px}.file:last-child{border-bottom:0}.file span:first-child{flex:1;overflow-wrap:anywhere}.status{color:var(--sub);font-size:14px;margin-top:10px}.ok{color:var(--good);font-weight:700}.stopBox{margin-top:22px;text-align:right}.guide{margin:0;padding-left:18px;color:var(--sub)}@media(min-width:900px){.sectionGrid{grid-template-columns:1fr 1fr}.subgrid{grid-template-columns:1fr 1fr}}
</style></head><body><div class="wrap"><div class="hero"><h1>ファイル転送</h1><p>{{.DeviceName}} で iPhone / Android とファイルをやり取りします。案内に沿って 1 → 2 → 3 の順に進めてください。</p></div>
<div class="layout">
<div class="card"><div class="stepHead"><div class="stepNo">1</div><div><div class="stepTitle">スマホをこのWi‑Fiに接続</div><div class="lead">まずスマホのカメラでQRコードを読み取り、転送専用Wi‑Fiへ接続します。</div></div></div><div class="pair">{{if .WiFiQR}}<img class="qr" src="/qr.svg?text={{urlquery .WiFiQR}}" alt="Wi-Fi接続用QRコード">{{end}}<div class="credBox"><div class="credTitle">Wi‑Fi名</div><div class="credValue">{{.WiFiSSID}}</div><div style="height:12px"></div><div class="credTitle">今回のパスワード</div><div class="credValue"><span class="codeLike">{{.WiFiPassword}}</span></div><div style="height:14px"></div><ul class="guide"><li>QRコードを読むだけで接続できます。</li><li>「インターネットなし」と表示されても正常です。</li><li>このパスワードは今回の転送終了後には使えません。</li></ul></div></div></div>
<div class="card"><div class="stepHead"><div class="stepNo">2</div><div><div class="stepTitle">スマホで転送ページを開く</div><div class="lead">Wi‑Fi接続後、このQRコードを読み取るとスマホの転送画面が開きます。</div></div></div><div class="sectionGrid">{{range .URLs}}<div class="urlCard"><div class="pair"><img class="qr" src="/qr.svg?text={{urlquery .URL}}" alt="転送ページ用QRコード"><div style="flex:1;min-width:230px"><div class="urlTop"><strong>{{.Interface}}</strong>{{if .Preferred}}<span class="tag">おすすめ</span>{{end}}</div><div class="muted" style="margin-top:6px">IPアドレス: {{.IP}}</div><div class="bigUrl">{{.URL}}</div><div class="muted" style="margin-top:10px">QRコードを読めない場合だけ、上のURLを手入力してください。</div></div></div></div>{{else}}<div class="warn">転送用ネットワークを確認できませんでした。アプリをいったん終了して、Wi‑Fiの状態を確認してください。</div>{{end}}</div></div>
<div class="card"><div class="stepHead"><div class="stepNo">3</div><div><div class="stepTitle">ファイルを送受信する</div><div class="lead">スマホ → PC はスマホ側から、PC → スマホ はこの画面から共有します。</div></div></div><div class="toolRow"><label class="fileLabel primary">PCからスマホへ送るファイルを選ぶ<input id="sharePick" type="file" multiple></label><button class="btn secondary" onclick="openFolder('send')">送信用フォルダーを開く</button><button class="btn secondary" onclick="openFolder('receive')">受信フォルダーを開く</button></div><div id="shareStatus" class="status"></div><div class="subgrid"><div class="panel"><h3>PC → スマホ 共有中</h3><div class="muted">ここにあるファイルがスマホ側に表示されます。</div><div id="sendList" class="list"></div><button class="btn danger" onclick="clearSide('send')" style="margin-top:12px">共有をすべて解除</button></div><div class="panel"><h3>スマホ → PC 受信済み</h3><div class="muted">スマホから送られたファイルです。</div><div id="recvList" class="list"></div><button class="btn danger" onclick="clearSide('receive')" style="margin-top:12px">受信ファイルをすべて削除</button></div></div></div>
<div class="card stopBox"><button class="btn danger" onclick="stopApp()">転送を終了する</button><div class="muted" style="margin-top:8px">終了すると、転送用Wi‑Fiとスマホ側の転送ページが使えなくなります。</div></div>
</div></div>
<script>
const admin='/admin/{{.AdminToken}}';
function fmt(n){if(n<1024)return n+' B';if(n<1048576)return(n/1024).toFixed(1)+' KB';if(n<1073741824)return(n/1048576).toFixed(1)+' MB';return(n/1073741824).toFixed(2)+' GB'}
document.getElementById('sharePick').addEventListener('change',async e=>{const st=document.getElementById('shareStatus');for(const f of e.target.files){st.textContent='共有準備中: '+f.name;await rawUpload(f)}st.textContent='共有ファイルを更新しました。スマホ側で受け取れます。';st.className='status ok';e.target.value='';loadStatus()});
function rawUpload(f){return new Promise(res=>{const x=new XMLHttpRequest();x.open('POST',admin+'/upload?name='+encodeURIComponent(f.name));x.onload=()=>res();x.onerror=()=>res();x.send(f)})}
async function openFolder(which){await fetch(admin+'/open?which='+which,{method:'POST'})}
async function clearSide(which){if(!confirm(which==='send'?'スマホ向けの共有ファイルをすべて解除しますか？':'受信済みファイルをすべて削除しますか？'))return;await fetch(admin+'/clear-'+which,{method:'POST'});loadStatus()}
async function loadStatus(){try{const r=await fetch(admin+'/api/status',{cache:'no-store'});const s=await r.json();render('sendList',s.send,'共有中のファイルはありません');render('recvList',s.receive,'まだ受信ファイルはありません')}catch(e){}}
function render(id,fs,empty){const el=document.getElementById(id);if(!fs.length){el.innerHTML='<div class="muted" style="padding:10px 0">'+empty+'</div>';return}el.innerHTML='';for(const f of fs){const d=document.createElement('div');d.className='file';const n=document.createElement('span');n.textContent=f.name;const z=document.createElement('span');z.className='muted';z.textContent=fmt(f.size);d.append(n,z);el.appendChild(d)}}
async function stopApp(){if(!confirm('ファイル転送を終了しますか？'))return;await fetch(admin+'/stop',{method:'POST'});document.body.innerHTML='<div style="font-family:Segoe UI,sans-serif;max-width:650px;margin:80px auto;padding:28px"><h1>転送を終了しました</h1><p>このタブを閉じてください。</p></div>'}
loadStatus();setInterval(loadStatus,3000);
</script></body></html>`))
